import { copyFile, lstat, mkdir, mkdtemp, readFile, readdir, realpath, rename, rm, unlink, writeFile } from 'node:fs/promises';
import { constants } from 'node:fs';
import { createReadStream } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';
import { homedir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// A private workspace transfer is distinct from the data-free public release.
// The source archive must first be regenerated by the fully guarded export.
const root = await realpath(fileURLToPath(new URL('../', import.meta.url)));
const downloads = path.join(homedir(), 'Downloads');
const delivery = path.join(downloads, '点到-2026-10-11');
const includeData = process.argv.includes('--include-data');
const date = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai' }).format(new Date());
const destination = path.join(downloads, `SlateRandom-岩选-工作区迁移-${date}.zip`);
const sourceArchive = path.join(root, '点到-完整源码.zip');
const release = path.join(root, 'release');
const report = JSON.parse(await readFile(path.join(root, 'qa-output/final-report.json'), 'utf8'));
const build = JSON.parse(await readFile(path.join(release, 'desktop-build.json'), 'utf8'));
const quote = value => "'" + value.replaceAll("'", "''") + "'";
async function hashFile(file) {
  const hash = createHash('sha256');
  for await (const chunk of createReadStream(file)) hash.update(chunk);
  return hash.digest('hex');
}
function powershell(script) {
  return new Promise((resolve, reject) => {
    const child = spawn('powershell.exe', ['-NoLogo', '-NoProfile', '-NonInteractive', '-Command', script], { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let log = '';
    for (const stream of [child.stdout, child.stderr]) stream.on('data', data => { log = (log + data).slice(-16000); });
    child.once('error', reject); child.once('close', code => code === 0 ? resolve() : reject(Error(log || 'Archive operation failed: ' + code)));
  });
}
async function ordinary(file, directory = false) {
  const info = await lstat(file);
  if (info.isSymbolicLink() || !(directory ? info.isDirectory() : info.isFile())) throw Error('Expected ordinary ' + (directory ? 'directory: ' : 'file: ') + file);
  return info;
}
async function checkDestination(file) {
  try { await ordinary(file); } catch (error) { if (error.code !== 'ENOENT') throw error; }
}
async function filesIn(directory, relative = '') {
  await ordinary(directory, true);
  const files = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const file = path.join(directory, entry.name), name = path.join(relative, entry.name);
    const info = await lstat(file);
    if (info.isSymbolicLink()) throw Error('Workspace transfer refuses links: ' + file);
    if (info.isDirectory()) files.push(...await filesIn(file, name));
    else if (info.isFile()) files.push({ source: file, name, bytes: info.size });
    else throw Error('Unsupported file in transfer: ' + file);
  }
  return files.sort((a, b) => a.name.localeCompare(b.name));
}
async function copyVerified(source, target) {
  await ordinary(source); await mkdir(path.dirname(target), { recursive: true });
  const originalHash = await hashFile(source); await copyFile(source, target);
  if (await hashFile(source) !== originalHash || await hashFile(target) !== originalHash) throw Error('A file changed while making the transfer: ' + source);
}
await ordinary(sourceArchive); await ordinary(path.join(root, 'HANDOFF.md'));
await ordinary(downloads, true); await checkDestination(destination); await checkDestination(destination + '.sha256');
const htmlHash = await hashFile(path.join(root, 'dist/index.html'));
if (htmlHash !== report.sha256.toLowerCase() || htmlHash !== build.htmlSHA256 || report.runtimeErrors.length || report.unitTests.failures) throw Error('Only the verified current build can be transferred.');
if (await hashFile(path.join(release, 'SlateRandom-win32-x64/resources/app.asar')) !== report.appAsarSha256.toLowerCase() || await hashFile(path.join(root, build.portableZip)) !== report.nativeZipSha256.toLowerCase()) throw Error('Native artifacts differ from the verified release.');

const staging = await mkdtemp(path.join(root, '.workspace-stage-'));
const outputPartial = destination + '.partial-' + path.basename(staging);
try {
  console.log('Preparing verified source and complete build artifacts.');
  await powershell(`$ErrorActionPreference='Stop';Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead(${quote(sourceArchive)});try{foreach($entry in $zip.Entries){$name=$entry.FullName.Replace([char]92,[char]47);if(!$name.StartsWith('源码/')){throw 'Unexpected source root'};$resolved=[IO.Path]::GetFullPath([IO.Path]::Combine(${quote(staging)},$entry.FullName));if(!$resolved.StartsWith(${quote(staging + path.sep)},[StringComparison]::OrdinalIgnoreCase)){throw 'Unsafe source archive entry'}}}finally{$zip.Dispose()};[IO.Compression.ZipFile]::ExtractToDirectory(${quote(sourceArchive)},${quote(staging)})`);
  const workspace = path.join(staging, 'SlateRandom-workspace');
  await rename(path.join(staging, '源码'), workspace);
  // Refuse an old source archive that predates these migration instructions.
  for (const file of await filesIn(workspace)) {
    if (await hashFile(path.join(root, file.name)) !== await hashFile(file.source)) throw Error('Regenerate the source archive with node scripts/export.mjs before transfer: ' + file.name);
  }
  for (const file of await filesIn(release)) {
    if (file.name.split(path.sep).some(part => part.toLowerCase() === 'data')) throw Error('Keep personal data out of the verified build directory.');
    await copyVerified(file.source, path.join(workspace, 'release', file.name));
  }
  await copyVerified(path.join(root, 'dist/index.html'), path.join(workspace, 'SlateRandom-Lite.html'));
  // Retain the evidence referenced by the final reports, not failed-run dumps.
  for (const name of await readdir(path.join(root, 'qa-output'))) {
    if (/^toolchain-(?:tests-.*\.tap|typecheck\.log)$/.test(name) || ['desktop-native-touch.json', 'performance-compatibility-report.json'].includes(name)) await copyVerified(path.join(root, 'qa-output', name), path.join(workspace, 'qa-output', name));
  }
  let personalFiles = 0, personalBytes = 0;
  if (includeData) {
    const sourceData = path.join(delivery, 'SlateRandom-win32-x64/data');
    const dataNames = new Set(['roster.json', 'settings.json', 'statistics.srstat', '.fairness-key', 'desktop-settings.json', '.state-transaction.json', '.portable-migration.json']);
    const currentFiles = async () => {
      await ordinary(sourceData, true);
      const selected = [];
      for (const name of await readdir(sourceData)) if (dataNames.has(name)) {
        const source = path.join(sourceData, name), info = await ordinary(source);
        selected.push({ source, name, bytes: info.size });
      }
      for (const required of ['roster.json', 'settings.json', 'statistics.srstat', '.fairness-key']) if (!selected.some(file => file.name === required)) throw Error('Portable data is incomplete: ' + required);
      return selected;
    };
    const snapshot = [];
    for (const file of await currentFiles()) {
      const target = path.join(workspace, 'migration-data/data', file.name);
      await copyVerified(file.source, target);
      snapshot.push({ source: file.source, hash: await hashFile(target) });
      personalFiles++; personalBytes += file.bytes;
    }
    if ((await currentFiles()).length !== snapshot.length) throw Error('Runtime data changed during transfer; close the application and retry.');
    for (const file of snapshot) if (await hashFile(file.source) !== file.hash) throw Error('Runtime data changed during transfer; close the application and retry.');
    const roster = JSON.parse(await readFile(path.join(workspace, 'migration-data/data/roster.json'), 'utf8'));
    const settings = JSON.parse(await readFile(path.join(workspace, 'migration-data/data/settings.json'), 'utf8'));
    const statistics = await readFile(path.join(workspace, 'migration-data/data/statistics.srstat'));
    if (roster.generation !== settings.generation || statistics.subarray(10, 26).toString('hex') !== roster.generation) throw Error('Portable snapshot spans different saves; close the application and retry.');
  }
  const files = await filesIn(workspace), manifestEntries = [];
  for (const file of files) manifestEntries.push({ path: file.name.replaceAll('\\', '/'), bytes: file.bytes, sha256: await hashFile(file.source) });
  const manifest = {
    format: 'SlateRandom.workspace', version: 1, createdAt: new Date().toISOString(), product: 'SlateRandom 岩选', author: 'DeepslateQAQ',
    htmlSha256: htmlHash, appAsarSha256: report.appAsarSha256.toLowerCase(), nativeZipSha256: report.nativeZipSha256.toLowerCase(),
    sourceArchiveSha256: await hashFile(sourceArchive), checks: report.checks.length, unitTests: report.unitTests.total,
    personalData: { included: personalFiles > 0, files: personalFiles, bytes: personalBytes, location: 'migration-data/data', originalUnchanged: true, browserProfileExcluded: true },
    dependencies: 'Restore node_modules with pnpm install --frozen-lockfile; download Electron with pnpm desktop:install.',
    excluded: ['node_modules', '.openai', '.migration-baseline', '.vite-build', 'old export/build staging', 'failed test profiles and screen captures'],
    manifestDoesNotHashItself: true, files: manifestEntries,
  };
  const manifestFile = path.join(workspace, 'WORKSPACE-MANIFEST.json');
  await writeFile(manifestFile, JSON.stringify(manifest, null, 2) + '\n', 'utf8');
  const expected = Object.fromEntries(manifestEntries.map(file => ['SlateRandom-workspace/' + file.path, { bytes: file.bytes, sha256: file.sha256 }]));
  expected['SlateRandom-workspace/WORKSPACE-MANIFEST.json'] = { bytes: (await lstat(manifestFile)).size, sha256: await hashFile(manifestFile) };
  const expectedFile = path.join(staging, 'expected.json'), archive = path.join(staging, 'workspace.zip');
  await writeFile(expectedFile, JSON.stringify(expected), 'utf8');
  console.log('Creating one workspace ZIP; personal data files: ' + personalFiles + '.');
  await powershell(`$ErrorActionPreference='Stop';Add-Type -AssemblyName System.IO.Compression.FileSystem;[IO.Compression.ZipFile]::CreateFromDirectory(${quote(workspace)},${quote(archive)},[IO.Compression.CompressionLevel]::Optimal,$true)`);
  console.log('Verifying every archive entry and SHA-256.');
  await powershell(`$ErrorActionPreference='Stop';Add-Type -AssemblyName System.IO.Compression.FileSystem;$expected=Get-Content -LiteralPath ${quote(expectedFile)} -Raw -Encoding UTF8|ConvertFrom-Json;$seen=@{};$zip=[IO.Compression.ZipFile]::OpenRead(${quote(archive)});$sha=[Security.Cryptography.SHA256]::Create();try{foreach($entry in $zip.Entries){$name=$entry.FullName.Replace([char]92,[char]47);if($name.EndsWith('/')){continue};$property=$expected.PSObject.Properties[$name];if(!$property -or $seen.ContainsKey($name)){throw ('Unexpected archive entry: '+$name)};if($entry.Length -ne $property.Value.bytes){throw ('Archive size mismatch: '+$name)};$stream=$entry.Open();try{$actual=[BitConverter]::ToString($sha.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$stream.Dispose()};if($actual -ne $property.Value.sha256){throw ('Archive SHA mismatch: '+$name)};$seen[$name]=$true};if($seen.Count -ne @($expected.PSObject.Properties).Count){throw 'Incomplete archive'}}finally{$sha.Dispose();$zip.Dispose()}`);
  const archiveHash = await hashFile(archive);
  // A migrated workspace can be on a different drive from Downloads.
  await copyFile(archive, outputPartial, constants.COPYFILE_EXCL);
  if (await hashFile(outputPartial) !== archiveHash) throw Error('Transfer copy SHA mismatch.');
  await rename(outputPartial, destination);
  await writeFile(destination + '.sha256', archiveHash + '  ' + path.basename(destination) + '\n', 'utf8');
  await copyVerified(path.join(root, 'HANDOFF.md'), path.join(downloads, 'SlateRandom-HANDOFF.md'));
  console.log(JSON.stringify({ archive: destination, bytes: (await lstat(destination)).size, sha256: archiveHash, files: Object.keys(expected).length, personalFiles, personalBytes, verified: true }));
} finally {
  await unlink(outputPartial).catch(error => { if (error.code !== 'ENOENT') throw error; });
  const verified = await realpath(staging);
  if (path.dirname(verified) !== root || !path.basename(verified).startsWith('.workspace-stage-')) throw Error('Refusing unexpected transfer staging cleanup.');
  await rm(verified, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
}
